ST.xhtml:p:
(*心跳包，写入0x3A，保证使能*)
g_noHeart_Beat := 58;

R_Trigger(CLK := g_bF050Home );
(*R_Trigger1(CLK := g_bFBM11XEnable OR g_bMnualAnalogEnable);*)

(*回零,F轴到0刻度*)
IF R_Trigger.Q THEN
  g_bF050Home := false;
  g_noPositionSetFocus := LREAL_TO_DINT(1000.0*g_dZeroFActPosion);
END_IF;

IF g_bFBM114EEnable THEN
  dFPosFb := g_dAnalogPosition;
  g_bFBM114EEnable := FALSE;
  g_bFocusEnable := FALSE;
  nState := 5;
ELSIF g_bMnualAnalogEnable THEN
  dFPosFb := g_dMnualAnalogPosition;
  g_bMnualAnalogEnable := FALSE;
  nState := 5;
END_IF;

CASE nState OF
  0:
    nState := 0;  
  5:  (*调焦*)
    g_dMOTO_PositionSet := 1000.0*g_dZeroFActPosion - 1000.0*dFPosFb;
    g_noPositionSetFocus := LREAL_TO_DINT(g_dMOTO_PositionSet);
    nState := 10;
  10:(*调焦完成*)
    IF g_niBM114EActualFocus>DINT_TO_INT(g_noPositionSetFocus)-50 AND g_niBM114EActualFocus< DINT_TO_INT(g_noPositionSetFocus)+50 THEN
      g_bFocusDone := TRUE;
      nState := 0;
    END_IF;
END_CASE;    

(*坐标反馈*)
g_dFaxisAnoagePosFb := (1000.0*g_dZeroFActPosion - INT_TO_LREAL(g_niBM114EActualFocus))/1000.0;
IF g_niBM114EBottomProtecWindowTemperAlarm = 2 THEN (*断线*)
    g_Alarm.alarmArray[355] := 1082;
  ELSIF g_niTemperature_ErrorCode = 3 THEN  (*超温*)
    g_Alarm.alarmArray[355] := 1083;
  ELSE
    g_Alarm.alarmArray[355] := 0;
  END_IF;
  IF g_niBM114EFocusMotorErrorCode <> 0 THEN   (*调焦电机报错*)
      g_Alarm.alarmArray[356] := 1084;
  ELSE
    g_Alarm.alarmArray[356] := 0;
  END_IF;
  (*调焦头使能警，2异常，1正常*)
IF g_niBM114EStatusEnable = 1 THEN
  g_Alarm.alarmArray[357] := 0;  
ELSE
  g_Alarm.alarmArray[357] := 1085;   
END_IF;
